193	  </head>
194	  <body>
195	    <header>
196	      <h1>Café René's Onion Ledger</h1>
197	      <p class="lede">
198	        "Ze finest recommendations, smuggled past ze checkpoint in a string of onions." Which models
199	        to use on GitHub Copilot and OpenCode Go, per kind of task — recomputed daily from provider
200	        pricing and Artificial Analysis benchmarks.
201	      </p>
202	      <div class="meta" id="meta"></div>
203	    </header>
204	
205	    <main id="app"><p class="empty">Setting ze tables…</p></main>
206	
207	    <footer>
208	      <p>
209	        Score is a weighted sum of min-max normalized metrics across all scored models. Blended
210	        price assumes 3 output tokens per input token. Pricing:
211	        <a href="https://docs.github.com/en/copilot/reference/copilot-billing/models-and-pricing"
212	          >GitHub Copilot docs</a
213	        >, <a href="https://opencode.ai/docs/go/">OpenCode Go docs</a>. Benchmarks:
214	        <a href="https://artificialanalysis.ai/">Artificial Analysis</a>. Source:
215	        <a href="https://github.com/KuzniAI/onion-sellers">KuzniAI/onion-sellers</a>. Inspired by
216	        René's onion-selling disguise in 'Allo 'Allo!.
217	      </p>
218	    </footer>
219	
220	    <script>
221	      const PROVIDERS = [
222	        { id: "copilot", name: "GitHub Copilot" },
223	        { id: "opencode-go", name: "OpenCode Go" },
224	      ];
225	      const WEIGHT_LABELS = {
226	        agenticIndex: "Agentic",
227	        codingIndex: "Coding",
228	        intelligenceIndex: "Intelligence",
229	        costEfficiency: "Cost efficiency",
230	        speed: "Speed",
231	      };
232	      const STALE_MS = 36 * 60 * 60 * 1000;
233	
234	      const ESCAPES = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };
235	      const esc = (value) => String(value).replace(/[&<>"']/g, (c) => ESCAPES[c]);
236	      const num = (value, digits = 1) =>
237	        value == null ? "–" : value.toLocaleString(undefined, { maximumFractionDigits: digits });
238	      const fmtDate = (iso) =>
239	        new Date(iso).toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" });
240	      const titleCase = (key) => {
241	        const words = key.replace(/([A-Z])/g, " $1").toLowerCase();
242	        return words[0].toUpperCase() + words.slice(1);
243	      };
244	
245	      async function getJson(url) {
246	        const res = await fetch(url);
247	        if (!res.ok) throw new Error(`${res.status} on ${url}`);
248	        return res.json();
249	      }
250	
251	      function renderMeta(recs, pricing) {
252	        const generatedAt = new Date(recs.generatedAt);
253	        const items = [
254	          `Updated <time datetime="${esc(recs.generatedAt)}">${esc(fmtDate(recs.generatedAt))}</time>`,
255	          `${num(recs.candidatesConsidered, 0)} models scored`,
256	        ];
257	        PROVIDERS.forEach((provider, i) => {
258	          const source = pricing[i];
259	          if (!source) {
260	            items.push(`${provider.name} pricing: unavailable`);
261	            return;
262	          }
263	          const stale = generatedAt - new Date(source.fetchedAt) > STALE_MS;
264	          items.push(
265	            `<a href="${esc(source.sourceUrl)}">${provider.name} pricing</a>: ${esc(fmtDate(source.fetchedAt))}` +
266	              (stale ? '<span class="badge">stale</span>' : ""),
267	          );
268	        });
269	        document.getElementById("meta").innerHTML = items.map((i) => `<span>${i}</span>`).join("");
270	      }
271	
272	      function renderTable(rows) {
273	        if (!rows?.length) return '<p class="empty">No scored models.</p>';
274	        const body = rows
275	          .map(
276	            (r, i) => `<tr>
277	              <td>${i + 1}</td>
278	              <td class="model">${esc(r.model)}</td>
279	              <td class="score">${num(r.score, 3)}</td>
280	              <td>${num(r.breakdown.agenticIndex)}</td>
281	              <td>${num(r.breakdown.codingIndex)}</td>
282	              <td>${num(r.breakdown.intelligenceIndex)}</td>
283	              <td>${num(r.breakdown.speed, 0)}</td>
284	              <td>$${num(r.priceBlendedPer1M, 3)}</td>
285	            </tr>`,
286	          )
287	          .join("");
288	        return `<div class="table-wrap"><table>
289	          <thead><tr>
290	            <th>#</th><th>Model</th><th>Score</th><th>Agentic</th><th>Coding</th>
291	            <th>Intel.</th><th>Tok/s</th><th>$/1M</th>
292	          </tr></thead>
293	          <tbody>${body}</tbody>
294	        </table></div>`;
295	      }
296	
297	      function renderCategory(name, byProvider, config) {
298	        const weights = Object.entries(config?.weights ?? {})
299	          .filter(([, w]) => w > 0)
300	          .sort((a, b) => b[1] - a[1])
301	          .map(([k, w]) => `<li>${esc(WEIGHT_LABELS[k] ?? k)} ${Math.round(w * 100)}%</li>`)
302	          .join("");
303	        const providers = PROVIDERS.map(
304	          (p) => `<div><h3>${p.name}</h3>${renderTable(byProvider[p.id])}</div>`,
305	        ).join("");
306	        return `<section class="category">
307	          <h2>${esc(titleCase(name))}</h2>
308	          ${config?.description ? `<p class="desc">${esc(config.description)}</p>` : ""}
309	          <ul class="weights">${weights}</ul>
310	          <div class="providers">${providers}</div>
311	        </section>`;
312	      }
313	
314	      async function main() {
315	        const app = document.getElementById("app");
316	        try {
317	          const [recs, config, ...pricing] = await Promise.all([
318	            getJson("data/recommendations.json"),
319	            getJson("categories.json").catch(() => ({ categories: {} })),
320	            ...PROVIDERS.map((p) => getJson(`data/${p.id}/models-pricing.json`).catch(() => null)),
321	          ]);
322	          renderMeta(recs, pricing);
323	          app.innerHTML = Object.entries(recs.categories)
324	            .map(([name, byProvider]) => renderCategory(name, byProvider, config.categories[name]))
325	            .join("");
326	        } catch (err) {
327	          app.innerHTML = `<p class="error">Could not load recommendations (${esc(err.message)}).</p>`;
328	        }
329	      }
330	
331	      main();
332	    </script>
333	  </body>
334	</html>
